                SCTP_TCB_LOCK_ASSERT(stcb);
        } else {
                sctp_unlock_assert(SCTP_INP_SO(inp));
        }
#endif
        if ((net) && (net->dest_state & SCTP_ADDR_OUT_OF_SCOPE)) {
