        if (stcb) {
                vrf_id = stcb->asoc.vrf_id;
        } else {
                vrf_id = inp->def_vrf_id;
        }
#endif
        /* fill in the HMAC digest for any AUTH chunk in the packet */
        if ((auth != NULL) && (stcb != NULL)) {
                sctp_fill_hmac_digest_m(m, auth_offset, auth, stcb, auth_keyid);
        }

